insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('si-is-viileichd-kaa-maria-callas-owa-waunn-de-pawlaatschn-primadonna-beim-heirichn-zum-singan-aufaungd-geed-kaana-mea-haam', 'Si is viileichd kaa Maria Callas, owa waunn de Pawlaatschn-Primadonna beim Heirichn zum Singan aufaungd, geed kaana mea haam!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Sie ist vielleicht keine Maria Callas, aber wenn die Pawlatschen-Primadonna beim Heurigen zu singen anfängt, geht keiner mehr heim!', '[{"kategorie": "wörtlich", "text": "\"Sie ist zwar nicht weltberühmt, aber wenn die Pawlatschen-Primadonna beim Heurigen zu singen beginnt, geht niemand mehr heim!\"  2. Sie mag keine große Operndiva sein, aber sobald sie im Innenhof ihre Stimme erhebt, hält der ganze Heurige den Atem an!  3. Man wird sie kaum an der Mailänder Scala hören – doch im Grätzel ist sie eine Institution: Die Pawlatschen-Primadonna, die beim Heurigen für magische Abende sorgt!"}]'::jsonb, ''),
  ('a-pawlaatschnkonzead-is-ned-nuara-event-es-is-a-schdickl-gleebda-weana-soeoe', 'A Pawlaatschnkonzead is ned nuara Event - es is a Schdickl gleebda Weana Söö!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Ein Pawlatschenkonzert ist nicht nur Event – es ist ein Stück gelebter Wiener Seele!', '[{"kategorie": "wörtlich", "text": "\"Ein Pawlatschenkonzert ist mehr als ein Event – es ist ein Stück gelebter Wiener Seele!\"  2. Ein Pawlatschenkonzert ist nicht nur ein Event – es ist ein klingendes Erbe, das den Takt des alten Wien auf Bretterbühnen in charmanten Innenhöfen zu neuem Leben erweckt!  3. Zwischen Laubengängen, Balkonen und Weingläsern klingt nicht nur Musik – ein Pawlatschenkonzert ist pures Wiener Lebensgefühl!"}]'::jsonb, ''),
  ('ois-eafoarana-pawlaatschntischla-kennda-a-jeeds-detaeu-von-de-oidn-laubmgaeng-augfaungan-bei-de-boikn-bis-hii-zua-letzdn-schraufn', 'Ois eafoarana Pawlaatschntischla kennda a jeeds Detäu von de oidn Laubmgäng - augfaungan bei de Boikn bis hii zua letzdn Schraufn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Als erfahrener Pawlatschentischler kennt er jedes Detail der alten Laubengänge – angefangen bei den Balken bis hin zur letzten Schraube!', '[{"kategorie": "wörtlich", "text": "\"Als erfahrener Pawlatschentischler kennt er jedes Detail der alten Laubengänge – vom Balken bis zur letzten Schraube!\"  2. Als erfahrener Pawlatschenbauer kennt er jeden Winkel der historischen Laubengänge – von der tragenden Konstruktion bis zur kleinsten Schraubverbindung!  3. Als ''Zimmermann der Innenhöfe'' ist er ein Fachmann für Hofgalerien und kennt jedes Detail – vom Holzprofil bis zur letzten Verstrebung!"}]'::jsonb, ''),
  ('a-pawlaatschntischla-is-da-aanziche-deara-haus-eipockn-deaf-oone-dass-a-geschenk-is', 'A Pawlaatschntischla is da aanziche, deara Haus eipockn deaf, oone dass a Geschenk is!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ein Pawlatschentischler ist der einzige, der ein Haus einpacken darf, ohne dass es ein Geschenk ist!', '[{"kategorie": "wörtlich", "text": "\"Ein Gerüstbauer ist der einzige, der ein Haus einpacken darf, ohne dass es ein Geschenk ist!\"  2. Wenn ein Haus wie eingepackt aussieht, war kein Künstler am Werk – sondern der Pawlatschentischler!  3. Andere wickeln Pralinen ein – der Pawlatschentischler wickelt dir gleich das ganze Haus ein!"}]'::jsonb, ''),
  ('muang-loss-i-ma-an-drochn-aum-oasch-peckn', 'Muang loss I ma an Drochn aum Oasch peckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Morgen lass ich mir einen Drachen auf den Arsch pecken!', '[{"kategorie": "wörtlich", "text": "\"Morgen lass ich mir einen Drachen auf den Hintern tätowieren!\"  2. Morgen bekomme ich ein Drachen-Tattoo auf meinen Allerwertesten tätowiert!  3. Morgen lass ich mir ein Drachen-Tatoo auf mein [[Popscherl]] stechen!"}]'::jsonb, ''),
  ('i-loss-mi-von-kaan-auf-dera-woeoed-peckn-aa-ned-von-dia', 'I loss mi von kaan auf dera Wööd peckn - aa ned von dia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich lass mich von keinem auf dieser Welt pecken - auch nicht von dir!', '[{"kategorie": "wörtlich", "text": "\"Ich lass mich von keinem auf dieser Welt drangsalieren - auch nicht von dir!\""}]'::jsonb, ''),
  ('des-flitschal-lossd-si-von-an-jeedn-peckn-dear-ia-an-hundata-zuaschdeckd', 'Des Flitschal lossd si von an jeedn peckn, dear ia an Hundata zuaschdeckd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Dieses Flitscherl lässt sich von jedem pecken, der ihr einen Hunderter zusteckt!', '[{"kategorie": "wörtlich", "text": "\"Dieses Flittchen lässt sich von jedem stechen, der ihr einen Hundert-Euro-Schein zusteckt!\"  2. Dieses leichte Mädchen schläft mit jedem, der sich mit einem Hunderter erkenntlich zeigt!  3. Diese Tussi lässt sich von jedem flachlegen, der zahlt!"}]'::jsonb, ''),
  ('oostaeia-peckn', 'Oostaeia peckn', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Ostereier pecken', '[{"kategorie": "wörtlich", "text": "\"Ostereier gegeneinanderstoßen\" (von \"pecken\"=\"mit dem Schnabel hacken\")"}, {"kategorie": "Osterbrauch, fig.", "text": "[[Eier pempern]], \"Ostereier aneinanderschlagen\", \"Ostereier ditschen\" (österliches Spiel, bei dem derjenige verliert, dessen Ei beim Anstoßen eingedrückt wird)"}]'::jsonb, 'Des Eia, wos beim Oostaeiapeckn häu bleibd, is a Symbol fian Sieg vom Leebm iwan Tood!'),
  ('des-eia-wos-beim-oostaeiapeckn-haeu-bleibd-is-a-symbol-fian-sieg-vom-leebm-iwan-tood', 'Des Eia, wos beim Oostaeiapeckn häu bleibd, is a Symbol fian Sieg vom Leebm iwan Tood!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Das Ei, das beim Ostereierpecken heil bleibt, ist ein Symbol für den Sieg des Lebens über den Tod!', '[{"kategorie": "wörtlich", "text": "\"Das heil gebliebene Ei gilt beim Ostereierpecken als Symbol des Lebens, das den Tod überwindet!\"  2. Das unversehrte Ei ist Sinnbild der Auferstehung Christi – des Lebens, das den Tod besiegt!  3. So wie das Ei beim Ostereierpecken unversehrt bleibt, so bleibt auch das göttliche Leben unzerstörbar!"}]'::jsonb, 'Oostaeia peckn'),
  ('eia-bempan', 'Eia bempan', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Eier pempern', '[{"kategorie": "wörtlich", "text": "\"Eier gegeneinanderstoßen\" (von [[pempern]]=\"stoßen\")"}, {"kategorie": "Osterbrauch, fig.", "text": "\"Eier pecken\", \"Ostereier aneinanderschlagen\", \"Ostereier ditschen\" (österliches Spiel, bei dem derjenige verliert, dessen Ei beim Anstoßen eingedrückt wird)"}]'::jsonb, 'Kinda und Eawochsane tuan Eia bempan - und vadeitlichn damit, dass es Leebm unzabrechlich is!'),
  ('kinda-und-eawochsane-tuan-eia-bempan-und-vadeitlichn-damit-dass-es-leebm-unzabrechlich-is', 'Kinda und Eawochsane tuan Eia bempan - und vadeitlichn damit, dass es Leebm unzabrechlich is!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Kinder und Erwachsene tun Eier pempern – und verdeutlichen damit, dass das Leben unzerbrechlich ist!', '[{"kategorie": "wörtlich", "text": "\"Kinder und Erwachsene pecken die Eier – und ohne viel Worte verdeutlichen sie damit, dass das Leben unzerbrechlich ist!\"  2. Kinder und Erwachsene pecken Ostereier – und zeigen damit, dass das Leben stärker ist als der Tod!  3. Beim Eierpecken feiern Kinder und Erwachsene die Auferstehung – das Leben, das nie zerbricht!"}]'::jsonb, 'Eia bempan'),
  ('eia-peckn', 'Eia peckn', '', '', '', 'Grundwortschatz Wienerisch', 'Eier pecken', '[{"kategorie": "wörtlich", "text": "\"Eier gegeneinanderstoßen\" (von \"pecken\"=\"mit dem Schnabel hacken\")"}, {"kategorie": "Osterbrauch, fig.", "text": "\"Ostereier aneinanderschlagen\", \"Ostereier ditschen\" (österliches Spiel, bei dem derjenige verliert, dessen Ei beim Anstoßen eingedrückt wird)"}]'::jsonb, 'Kinda und Eawochsane tuan Eia peckn - und vadeitlichn damit, dass es Leebm unzabrechlich is!'),
  ('kinda-und-eawochsane-tuan-eia-peckn-und-vadeitlichn-damit-dass-es-leebm-unzabrechlich-is', 'Kinda und Eawochsane tuan Eia peckn - und vadeitlichn damit, dass es Leebm unzabrechlich is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kinder und Erwachsene tun Eier pecken – und verdeutlichen damit, dass das Leben unzerbrechlich ist!', '[{"kategorie": "wörtlich", "text": "\"Kinder und Erwachsene pecken die Eier – und ohne viel Worte verdeutlichen sie damit, dass das Leben unzerbrechlich ist!\"  2. Kinder und Erwachsene pecken Ostereier – und zeigen damit, dass das Leben stärker ist als der Tod!  3. Beim Eierpecken feiern Kinder und Erwachsene die Auferstehung – das Leben, das nie zerbricht!"}]'::jsonb, 'Eia peckn'),
  ('fia-des-peckst-extra', 'Fia des peckst extra!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Für das peckst du extra', '[{"kategorie": "wörtlich", "text": "\"Dafür zahlst du extra!\"  2. (allg.) Hierfür musst du extra was berappen!  3. Dafür musst du extra was blechen!"}]'::jsonb, ''),
  ('dea-muass-fest-peckn', 'Dea muass fest peckn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat fest zu pecken!', '[{"kategorie": "wörtlich", "text": "\"Der hat tief in die Tasche zu greifen!\"  2. (allg.) Für den wird''s teuer!  3. Der hat ordentlich zu löhnen!"}]'::jsonb, ''),
  ('da-pecka-hod-meina-oidn-a-oaschgwei-peckd-schaud-echt-aus-wia-gedruckd', 'Da Pecka hod meina Oidn a Oaschgwei peckd - schaud echt aus wia gedruckd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Pecker hat meiner Alten ein Arschgeweih gepeckt - schaut echt aus wie gedruckt!', '[{"kategorie": "wörtlich", "text": "\"Der Tätowierer hat meiner Frau ein Arschgeweih gestochen - sieht echt aus wie gedruckt!\"  2. Der Tattoo-Künstler hat meiner Frau a richtig geschmeidiges Arschgeweih verpasst – schaut aus wie gemalt!  3. Der Tätowierer hat meiner Alten ein Geweih auf den Hintern gestochen - schaut echt aus, als hätt''s ein Laser gemacht!"}]'::jsonb, ''),
  ('dea-typ-is-a-echta-pecka-wo-a-weiwal-is-haengda-schoo-drau-mid-sein-beidl', 'Dea Typ is a echta Pecka - wo a Weiwal is, hängda schoo drau mid sein Beidl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der Typ ist ein echter Pecker - wo ein Weiberl ist, hängt er schon dran mit seinem Beidl!', '[{"kategorie": "wörtlich, sexuell", "text": "\"Der Typ ist ein echter Stecher - kaum sieht er ein Weibchen, wirft er sich mit seinem Schwanz auch schon an sie ran!\"  2. Der Kerl ist ein notorischer Aufreißer - der hängt sich mit seinem Pimmel an jede dran, die zwei Beine hat!  3. Der Typ ist unser ''Frauenstecher vom Dienst'' - immer auf der Pirsch und mit seinem Pimmel hinter jeder her, die Schatten wirft!"}]'::jsonb, ''),
  ('kaan-pecka-mochn', 'kaan Pecka mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Pecker machen', '[{"kategorie": "wörtlich, sexuell", "text": "\"keinen Stich machen\""}, {"kategorie": "sexuell", "text": "\"nicht zum Stechen kommen\", \"nicht landen\", \"nicht zum Einlochen kommen\", [[kaan]] Foara mochn"}]'::jsonb, 'Dea brood bei dera Blondn wiara notgäula Hengst - owa Pecka mochda kaan!'),
  ('dea-brood-bei-dera-blondn-wiara-notgaeula-hengst-owa-pecka-mochda-kaan', 'Dea brood bei dera Blondn wiara notgäula Hengst - owa Pecka mochda kaan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der brät bei der Blonden wie ein notgeiler Hengst - aber Stich macht er keinen!', '[{"kategorie": "wörtlich", "text": "\"Der baggert bei der Blonden wie ein notgeiler Hengst – aber zum Stechen kommt er nicht!\"  2. Der flirtet mit der Blonden wie ein liebestoller Kater - aber landen tut er nicht!  3. Der hängt an der Blonden wie ein heißgelaufener Gockel - zum Einlochen kommt er aber trotzdem nicht!"}]'::jsonb, 'kaan Pecka mochn'),
  ('dea-hod-an-uandlichn-pecka', 'Dea hod an uandlichn Pecka!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat einen ordentlichen Pecker!', '[{"kategorie": "wörtlich", "text": "\"Der hat einen gehörigen Dachschaden!\"  2. Der hat einen ordentlichen [[Sprung]] in der Schüssel!  3. (Deutschland): \"Der hat ordentlich einen an der Waffel!\""}]'::jsonb, ''),
  ('des-peckal-auf-sein-bizeps-schaud-aus-ois-haed-eams-a-blinda-min-loeoetkoibm-gschdochn', 'Des Peckal auf sein Bizeps schaud aus, ois häd eams a Blinda min Löötkoibm gschdochn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Peckerl auf seinem Bizeps schaut aus, als hätt''s ihm ein Blinder mit''m Lötkolben gestochen!', '[{"kategorie": "wörtlich", "text": "\"Das Tattoo auf seinem Bizeps schaut aus, als hätt''s ihm ein Blinder mit''m Lötkolben gestochen!\"  2. Das Tattoo auf seinem Bizeps sieht aus, als wär’s mit’m Schraubenzieher reingeritzt worden!  3. Die Tätowierung auf seinem Bizeps schaut aus, als hätte ein Pavian mit Parkinson versucht, einen Totenkopf zu stechen!"}]'::jsonb, ''),
  ('des-eia-wos-beim-eiaditschn-haeu-bleibd-is-a-symbol-fian-sieg-vom-leebm-iwan-tood', 'Des Eia, wos beim Eiaditschn häu bleibd, is a Symbol fian Sieg vom Leebm iwan Tood!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Ei, das beim Ostereierpecken heil bleibt, ist ein Symbol für den Sieg des Lebens über den Tod!', '[{"kategorie": "wörtlich", "text": "\"Das heil gebliebene Ei gilt beim Ostereierpecken als Symbol des Lebens, das den Tod überwindet!\"  2. Das unversehrte Ei ist Sinnbild der Auferstehung Christi – des Lebens, das den Tod besiegt!  3. So wie das Ei beim Ostereierpecken unversehrt bleibt, so bleibt auch das göttliche Leben unzerstörbar!"}]'::jsonb, ''),
  ('de-peckn-auf-eam-umanaund-ois-wara-da-letzte-dreck', 'De peckn auf eam umanaund, ois wara da letzte Dreck!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die pecken auf ihm herum, als wär'' er der letzte Dreck!', '[{"kategorie": "wörtlich", "text": "\"Die hacken auf ihm herum, als wär'' er der letzte Dreck!\"  2. Die hacken auf ihm rum, als müsste er für alles Elend der Welt büßen!  3. Die machen ihn fertig, als wäre er nur Dreck unter ihren Schuhen!"}]'::jsonb, ''),
  ('mei-oide-peckd-auf-mia-umadum-ois-warad-i-ia-peasoenlicha-blitzobleita', 'Mei Oide peckd auf mia umadum, ois warad I ia peasönlicha Blitzobleita!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Alte peckt auf mir herum, als wäre ich ihr persönlicher Blitzableiter!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte hackt auf mir herum, als wäre ich ihr persönlicher Blitzableiter!\"  2. Meine Frau nörgelt an mir rum, als wär ich schuld an allem, was in ihrem Leben schiefläuft!  3. Meine Alte hackt auf mir rum, als wär ich ihr seelischer Mistkübel!"}]'::jsonb, ''),
  ('i-tua-da-de-schnitzln-vuaklopfn-und-eipeckn-daunn-brauchsdas-nuo-no-panian', 'I tua da de Schnitzln vuaklopfn und eipeckn, daunn brauchsdas nuo no panian!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ich tu dir die Schnitzel vorklopfen und einpecken, dann brauchst du sie nur noch zu panieren!', '[{"kategorie": "wörtlich", "text": "\"Ich werde dir die Schnitzel vorklopfen und die Fleischränder leicht einschneiden - dann sind sie küchenfertig, und du brauchst sie nur noch zu panieren!\"  2. Ich bereite dir die Schnitzel vor – klopfe und ritze sie ein – du musst sie dann nur noch panieren!  3. Ich mach dir die Schnitzel küchenfertig – klopfen, einpecken, alles inklusive. Panieren kannst du sie ja wohl selbst, oder?"}]'::jsonb, ''),
  ('muassd-schdaendich-aufn-neichn-kolleegn-eipeckn-dea-is-doch-aeae-schoo-waachkochd-gmua', 'Muassd schdändich aufn neichn Kolleegn eipeckn? - Dea is doch ää schoo waachkochd gmua!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Musst du ständig auf den neuen Kollegen einpecken? - Der ist doch eh schon genug weichgekocht!', '[{"kategorie": "wörtlich", "text": "\"Musst du in einer Tour auf dem neuen Kollegen herumhacken? – Der ist doch eh schon total weichgekocht!\"  2. Warum gehst du dauernd auf den neuen Kollegen los? - Der ist doch eh schon komplett eingeschüchtert!  3. Musst du den neuen Kollegen ständig kritisieren? – Der ist doch eh schon völlig verunsichert!"}]'::jsonb, ''),
  ('waunnsd-wos-gscheids-wueuesd-muassd-hoid-noo-uandlich-wos-draufpeckn-bua', 'Waunnsd wos Gscheids wüüsd, muassd hoid noo uandlich wos draufpeckn, Bua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du was Gescheites willst, musst du halt noch ordentlich was draufpecken, Bub!', '[{"kategorie": "wörtlich", "text": "\"Wenn du was Gescheites willst, musst du halt noch ordentlich was drauflegen, Junge!\"  2. Wenn du was Vernünftiges willst, musst du halt ordentlich was aufzahlen, Alter!  3. Gute Sachen gibt’s nicht zum Nulltarif, da musst du halt noch ordentlich was draufbuttern, mein Junge!"}]'::jsonb, ''),
  ('muassd-jetzt-du-aa-no-so-draufpeckn-auf-des-oame-mentsch', 'Muassd jetzt du aa no so draufpeckn auf des oame Mentsch?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Musst du jetzt auch noch draufpecken auf das arme Mentsch?', '[{"kategorie": "wörtlich", "text": "\"Musst du jetzt auch noch auf dem armen Mädchen herumhacken?\"  2. Musst du das arme Mädel jetzt auch noch so runterputzen?  3. Ist es nicht schon schlimm genug? Musst du jetzt auch noch auf dem armen Mädchen so rumhacken?"}]'::jsonb, ''),
  ('si-oopeckn', 'si oopeckn', '', '', '', 'Grundwortschatz Wienerisch', 'sich abpecken', '[{"kategorie": "wörtlich", "text": "\"sich abpecken\" (Kompositum aus dem abtrennbaren Präfix [[ab]]=\"weg\" und [[pecken]]=\"hauen\")"}, {"kategorie": "allg.", "text": "\"sich weghauen\", \"sich abhauen\", \"sich krumm und bucklig lachen\", \"sich kringeln vor Lachen\", \"sich schieflachen\", [[sich zerkugeln vor Lachen]], [[sich abbröseln]]"}]'::jsonb, 'I peck mi oo!'),
  ('de-taubm-haum-olle-breesl-vom-boodn-wegpeckd', 'De Taubm haum olle Breesl vom Boodn wegpeckd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Tauben haben alle Brösel vom Boden weggepickt!', '[{"kategorie": "wörtlich", "text": "\"Die Tauben haben alle Krümel vom Boden aufgepickt und verschluckt!\"  2. Die Tauben haben jeden letzten Krümel aufgepickt und und restlos vertilgt!  3. Die Tauben haben alle Brösel vom Boden weggefuttert!"}]'::jsonb, ''),
  ('ea-hod-eam-de-freindin-wegpeckd', 'Ea hod eam de Freindin wegpeckd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Er hat ihm die Freundin weggepeckt!', '[{"kategorie": "wörtlich", "text": "\"Er hat ihm die Freundin weggeschnappt!\"  2. Er hat ihm die Alte abspenstig gemacht!\"  2. Er hat ihm die Frendin ausgespannt!"}]'::jsonb, ''),
  ('si-zapeckn', 'si zapeckn', '', '', '', 'Grundwortschatz Wienerisch', 'sich zerpecken', '[{"kategorie": "wörtlich", "text": "\"sich zerpecken\" (Kompositum aus dem unabtrennbaren Präfix [[zer-]]=\"auseinander\" und [[pecken]]=\"hauen\")"}, {"kategorie": "allg.", "text": "\"sich weghauen\", \"sich abhauen\", \"sich krumm und bucklig lachen\", \"sich schieflachen\", [[sich zerkugeln vor Lachen]], [[sich]] abbröseln, [[sich]] zerbären, [[sich]] zerfransen, [[sich]] zernegern, [[sich]] zerscheppern"}]'::jsonb, 'I kennd mi zapeckn - so deppad wia dea Dillo schoo wiida daheareed!'),
  ('i-kennd-mi-zapeckn-so-deppad-wia-dea-dillo-schoo-wiida-daheareed', 'I kennd mi zapeckn - so deppad wia dea Dillo schoo wiida daheareed!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich könnte mich zerpecken - so deppert wie der Dillo schon wieder daherredet!', '[{"kategorie": "wörtlich", "text": "\"Ich könnte mich schieflachen - so deppert wie der Schwindliche da wieder daherredet!\"  2. Ich könnt mich wegschmeißen – so saudumm wie der Depp da wieder daherquatscht!  3. Ich könnt mich zerkugeln vor Lachen – so bescheuert wie der Schwurbler da wieder daherlabert!"}]'::jsonb, ''),
  ('in-peedasueue-kaunnsd-ruhig-grob-zsaummpeckn-dea-kummd-aeae-nua-ois-deko-oobm-drauf', 'In Peedasüü kaunnsd ruhig grob zsaummpeckn - dea kummd ää nua ois Deko oobm drauf!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Den Petersil kannst du ruhig grob zusammenpecken - der kommt eh nur als Deko obendrauf!', '[{"kategorie": "wörtlich", "text": "\"Die Petersilie kannst du ruhig grob zusammenhacken – sie kommt eh nur als Deko drauf!\"  2. Hack die Petersilie ruhig grob zusammen – kommt sowieso bloß als Grünzeug obendrauf!  3. Die Petersilie kann grob gehackt werden, da sie lediglich zur Dekoration dient!"}]'::jsonb, ''),
  ('da-schaeaef-hod-mi-vua-olle-kolleeng-zsaummpeckd-ned-laut-owa-so-gnoodnlos-dass-echt-waeae-taun-hod', 'Da Schääf hod mi vua olle Kolleeng zsaummpeckd - ned laut, owa so gnoodnlos, dass echt wää taun hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Chef hat mich vor allen Kollegen zusammengepeckt - nicht laut, aber so gnadenlos, dass es echt wehgetan hat!', '[{"kategorie": "wörtlich", "text": "\"Der Chef hat mich vor allen Kollegen zusammengestutzt – nicht laut, aber so gnadenlos, dass es richtig weh getan hat!\"  2. Mein Boss hat mich vor allen Kollegen auseinandergenommen – nicht laut, aber so eiskalt, dass es echt wehgetan hat!  3. Mein Chef hat mich vor allen Leuten niedergemacht – nicht durch Lautstärke, sondern durch eiskalte, verletzende Worte!"}]'::jsonb, ''),
  ('mei-oide-hod-si-von-so-an-schlaumpnpecka-a-oaschgwei-aum-hintan-schdechn-lossn', 'Mei Oide hod si von so an Schlaumpnpecka a Oaschgwei aum Hintan schdechn lossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Meine Alte hat sich von so einem Schlampenpecker ein Arschgeweih auf den Hintern stechen lassen!', '[{"kategorie": "wörtlich", "text": "\"Meine Alte hat sich von so ’nem Steißbeinstecher ein Arschgeweih auf den Hintern tätowieren lassen!\"  2. Meine Alte war beim ''Steißbein-Michelangelo'' - jetzt hat sie ein Arschgeweih auf dem Hintern!  3. Meine Freundin hat sich von so ''nem 90er-Jahre-Tätowierer ein Tribal auf den Arsch stempeln lassen!"}]'::jsonb, ''),
  ('si-is-ausn-ualaub-zruck-frisch-gebraeund-und-mit-an-schlaumpnpeckal-iwan-oasch-des-leicht-wiara-bauschdoeoenschueued', 'Si is ausn Ualaub zruck - frisch gebräund und mit an Schlaumpnpeckal iwan Oasch, des leicht wiara Bauschdöönschüüd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie ist aus dem Urlaub zurück – frisch gebräunt und mit einem Schlampenpeckerl über''m Arsch, das leuchtet wie ein Baustellenlicht!', '[{"kategorie": "wörtlich", "text": "\"Sie ist aus dem Urlaub zurück – frisch gebräunt und mit einem Tribal überm Arsch, das leuchtet wie ein Baustellenlicht!\"  2. Sie ist zurück aus Malle – braun gebrannt und mit ’nem Arschgeweih, das blinkt wie ’ne Discokugel!  3. Kaum aus dem Urlaub daheim, leuchtet ihr Hintern wie ’n Leuchtturm – dank Arschgeweih-Tattoo aus dem Touristenstudio, das sich außer ihr heute wohl keiner mehr stechen lassen würde!"}]'::jsonb, ''),
  ('a-oaschwinjettnpeckal-is-wiara-schlechta-ex-es-geed-nimma-weg-owa-olle-seengs', 'A Oaschwinjettnpeckal is wiara schlechta Ex - es geed nimma weg, owa olle seengs!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Arschvignettenpeckerl ist wie ein schlechter Ex – es geht nicht mehr weg, aber alle sehen’s!', '[{"kategorie": "wörtlich", "text": "\"Ein Arschgeweih-Tattoo ist wie ein schlechter Ex – es geht nicht mehr weg, aber alle sehen’s!\"  2. So ein Tribal am Steißbein ist wie ein peinlicher One-Night-Stand: verblasst nie ganz und taucht immer dann auf, wenn’s keiner sehen soll!  3. Ein Steißbein-Tattoo ist wie ein Ex, der dir auf Social Media folgt – du willst ihn vergessen, aber er ist immer noch da!"}]'::jsonb, ''),
  ('dea-oaschwinjettnpecka-hod-ia-a-schlaumpn-tattuu-gritzd-jetzd-rennds-umanaund-wiara-tussi-aus-de-90-a', 'Dea Oaschwinjettnpecka hod ia a Schlaumpn-Tattuu gritzd - jetzd rennds umanaund wiara Tussi aus de 90-a!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Arschvignettenpecker hat ihr ein Schlampentattoo geritzt - jetzt rennt sie herum wie ''ne Tussi aus den 90-ern!', '[{"kategorie": "wörtlich", "text": "\"Der Steißbeinstecher hat ihr ein Schlampentattoo geritzt - jetzt rennt sie mit einem Arschgeweihstempel herum wie ''ne Tussi aus den 90-ern!\"  2. Der Popo-Pikser hat ihr ein Schlampenlogo verpasst – jetzt läuft sie mit einem Arschgeweih herum wie ein ''Bravo-Girlie'' aus den 90-ern!  3. Das Tattoo sitzt über ihrem Steiß wie ein Relikt verlorener Zeiten – ein Arschgeweih vom Trampstamp-Tätowierer!"}]'::jsonb, ''),
  ('a-oaschgweihpeckal-is-wiara-peinlicha-woan-neit-staend-vablossd-nii-gaunz-und-tauchd-imma-daunn-auf-waunns-kaana-seeng-soi', 'A Oaschgweihpeckal is wiara peinlicha ''Woan-Neit-Ständ'' - vablossd nii gaunz und tauchd imma daunn auf, waunns kaana seeng soi!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Arschgeweihpeckerl ist wie ein peinlicher One-Night-Stand: verblasst nie ganz und taucht immer dann auf, wenn’s keiner sehen soll!', '[{"kategorie": "wörtlich", "text": "\"Ein Arschgeweih-Tattoo ist wie ein peinlicher One-Night-Stand: verblasst nie ganz und taucht immer dann auf, wenn’s keiner sehen soll!\"  2. Das Tattoo über’m Hintern ist wie ein Partyfoto aus 2003 – man wünscht sich, das Arschgeweih wär gelöscht, aber es lebt auf dem Rücken weiter!  3. Das Steiß-Tattoo ist wie ein lästiges Kapitel aus deiner Vergangenheit – du hast’s vergessen, aber dein Rücken hat’s für immer archiviert!"}]'::jsonb, ''),
  ('da-oaschgweipecka-is-quasi-da-schlaumpnschdecha-aus-de-90-a-kaane-wueues-zuageem-owa-fost-jeede-woa-moi-do', 'Da Oaschgweipecka is quasi da Schlaumpnschdecha aus de 90-a - kaane wüüs zuageem, owa fost jeede woa moi do!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Arschgeweihpecker ist quasi der Schlampenstecher aus den 90-er Jahren - keine will’s zugeben, aber fast jede war mal da!', '[{"kategorie": "wörtlich", "text": "\"Der Trampstamp-Tätowierer ist quasi der Schlampenstecher aus den 90-er Jahren - keine will’s zugeben, aber fast jede war mal da!\"  2. Der Trampstamp-Künstler ist quasi der Tattoo-Friseur der 90-er Popkultur – jede war mal dort, aber heute fühlt man beim Anblick nur noch Retro-Schmerz!  3. Der Popo-Pisker war in den 90-ern Kult – jede dachte, das Tribal wär sexy, heute tut’s beim Hinsehen weh!"}]'::jsonb, ''),
  ('de-peleriin-pickd-eam-wiara-a-nossa-sock-aum-oasch-owa-hauptsoch-trockn', 'De Peleriin pickd eam wiara a nossa Sock aum Oasch - owa Hauptsoch trockn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Pelerine klebt ihm wie ein nasser Sack am Arsch, aber Hauptsache trocken!', '[{"kategorie": "wörtlich", "text": "\"Die Pelerine klebt wie ein nasser Müllsack an seinem Hintern, aber wenigstens läuft nichts rein!\"  2. Die Regenhaut klebt ihm am Rücken wie Schweißfolie – aber sie hält wenigstens trocken!  3. Die Pelerine ist wie ''ne kalte Plastikhülle auf warmer Haut – eklig, aber besser als durchgeweicht!"}]'::jsonb, ''),
  ('zwischn-perron-und-gleis-liigd-a-tooda-voogl', 'Zwischn Perron und Gleis liigd a tooda Voogl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zwischen Perron und Gleis liegt ein toter Vogel!', '[{"kategorie": "wörtlich", "text": "\"Zwischen Bahnsteigkante und Schiene liegt ein toter Vogel!\"  2. Zwischen Plattform und Schienen liegt ein verendeter Vogel!  3. Ein Vogel liegt leblos zwischen Perron und Gleis!"}]'::jsonb, ''),
  ('friara-is-a-jeeds-keenigliche-edikt-vom-kanzleischreiwa-soagfoeoetich-aufgroid-und-mit-an-roodn-wochs-petschiad-wuan', 'Friara is a jeeds keenigliche Edikt vom Kanzleischreiwa soagföötich aufgroid und mit an roodn Wochs petschiad wuan!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher ist jedes königliche Edikt vom Kanzleischreiber sorgfältig aufgerollt und mit rotem Wachs petschiert worden!', '[{"kategorie": "wörtlich", "text": "\"Früher wurde jedes königliche Edikt vom Kanzleischreiber sorgfältig aufgerollt und mit rotem Wachs gesiegelt!\"  2. Die königlichen Erlässe wurden früher vom Kanzleischreiber mit Wachs versiegelt, um ihre Echtheit zu garantieren!  3. Jedes königliche Edikt wurde vom Hofsekretär in Pergament gehüllt, mit Wachs getränkt und unter dem Zeichen der Krone versiegelt! (siehed auch [[petschian]])"}]'::jsonb, ''),
  ('nooch-den-peinlichn-auftritt-woara-fia-olle-zeitn-petschiad-ois-inkompetenta-daumpfplaudara', 'Nooch den peinlichn Auftritt woara fia olle Zeitn petschiad - ois inkompetenta Daumpfplaudara!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Nach dem peinlichen Auftritt war er für alle Zeiten petschiert – als inkompetenter Dampfplauderer!', '[{"kategorie": "wörtlich", "text": "\"Nach dem peinlichen Auftritt war er für alle Zeiten gebrandmarkt – als inkompetenter Blender!\"  2. Nach seinem peinlichen Auftritt haftete ihm dauerhaft der Ruf eines inkompetenten Selbstdarstellers an!  3. Seit dem peinlichen Auftritt war er mit dem Stigma des selbstverliebten Dilettanten gebrandmarkt!"}]'::jsonb, ''),
  ('da-schitstoam-im-netz-hod-eam-bis-aufd-knochn-petschiad', 'Da Schitstoam im Netz hod eam bis aufd Knochn petschiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Shitstorm im Netz hat ihn bis auf die Knochen petschiert!', '[{"kategorie": "wörtlich", "text": "\"Der Shitstorm im Netz hat ihn bis auf die Knochen blamiert!\"  2. Seit dem Shitstorm im Netz ist er öffentlich gebrandmarkt!  3. Die virale Entrüstungswelle im Netz hat ihn bis auf die Knochen bloßgestellt – seither trägt er das Stigma sichtbar auf der Stirn!"}]'::jsonb, ''),
  ('zeaschd-woas-valiabd-daunn-vafiad-und-jetzt-is-petschiad', 'Zeaschd woas valiabd, daunn vafiad - und jetzt is petschiad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Zuerst war sie verliebt, dann verführt – und jetzt ist sie petschiert! (Spaßreim)', '[{"kategorie": "wörtlich", "text": "\"Zuerst war sie verliebt, dann verführt – und jetzt trägt sie den Schwangerschaftsstempel auf ihrem Bauch!\"  2. \"Zuerst war sie verliebt, dann verführt – und jetzt ist sie schwanger!\"  3. \"Zuerst war sie verliebt, dann wurde sie verführt - und jetzt ist sie guter Hoffnung!\""}]'::jsonb, ''),
  ('de-nochricht-woa-auf-peagament-gschriem-und-mid-an-roodn-siiglwochs-petschiad', 'De Nochricht woa auf Peagament gschriem und mid an roodn Siiglwochs petschiad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Nachricht war auf Pergament geschrieben und mit rotem Siegelwachs petschiert!', '[{"kategorie": "wörtlich", "text": "\"Die Nachricht war in sorgfältiger Handschrift auf Pergament verfasst und mit dem roten Siegelwachs des Hauses versehen!\"  2. Die Depesche war mit rotem Wachs verschlossen und auf feinstem Pergament verfasst!  3. Auf sprödem Pergament stand die Nachricht, fest verschlossen durch ein Siegel aus blutrotem Wachs!"}]'::jsonb, ''),
  ('i-bin-petschiad', 'I bin petschiad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin petschiert', '[{"kategorie": "wörtlich", "text": "\"Ich bin für alle Zeit gebrandmarkt!\"  2. \"Ich bin für immer mit einem Stigma belegt!\"  3. \"Mein Schicksal ist für alle Zeit besiegelt!\"  4.  Mein Ruf ist auf ewig ruiniert!  5. Ich bin erledigt – mein Name trägt jetzt ein digitales Brandzeichen!"}]'::jsonb, ''),
  ('da-notaa-hod-mei-testament-petschiad', 'Da Notaa hod mei Testament petschiad!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Notar hat mein Testament petschiert!', '[{"kategorie": "wörtlich", "text": "\"Der Notar hat mein Testament mit einem Petschaft gesiegelt!\"  2. Der Notar hat mein Testament mit einem Siegelstempel versehen und beglaubigt!  3. Der Notar hat mein Testament amtlich beurkundet und mit einem Siegelwachs geschlossen!"}]'::jsonb, ''),
  ('wos-da-wiina-ned-brauchd-liigd-im-pfandl-bisas-doch-wiida-brauchd', 'Wos da Wiina ned brauchd, liigd im Pfandl - bisas doch wiida brauchd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Was der Wiener nicht braucht, liegt im Pfandl – bis er’s doch wieder braucht!', '[{"kategorie": "wörtlich", "text": "\"Was der Wiener nicht braucht, liegt im Pfandhaus – bis er’s doch wieder braucht!\"  2. Das Wiener Dorotheum - ein Pfandhaus, wo man alles hinschleppt, was man bald wieder vermisst!  3. Die Erinnerungen bringt man ins Pfandhaus, das schlechte Gewissen holt sie wieder ab!"}]'::jsonb, ''),
  ('fia-des-rezept-brauchsd-a-gusseisanes-pfandl-mit-an-deckl', 'Fia des Rezept brauchsd a gusseisanes Pfandl mit an Deckl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für dieses Rezept brauchst du eine gusseiserne Pfanne mit Deckel!', '[{"kategorie": "wörtlich", "text": "\"Für dieses Rezept brauchst du eine gusseiserne Bratpfanne, idealerweise mit Deckel!\"  2. Eine schwere, gusseiserne Pfanne mit passendem Deckel ist für dieses Rezept unerlässlich!  3. Für dieses Rezept empfiehlt sich eine gusseiserne Bratpfanne mit Deckel zur gleichmäßigen Hitzeverteilung!"}]'::jsonb, ''),
  ('ins-pfandl-troong', 'ins Pfandl troong', '', '', '', 'Wiener Sprüche, die sitzen!', 'ins Pfandl tragen', '[{"kategorie": "wörtlich", "text": "\"zur Pfandleihe tragen\""}, {"kategorie": "", "text": "\"ins Pfandhaus bringen\""}, {"kategorie": "", "text": "\"im Pfandhaus versetzen\""}, {"kategorie": "", "text": "\"beim Pfandleiher zu Geld machen\""}]'::jsonb, ''),
  ('waunns-goeoed-knopp-wiad-troog-i-in-bruella-von-meina-oidn-ins-pfandl', 'Waunns Gööd knopp wiad, troog I in Brülla von meina Oidn ins Pfandl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn das Geld knapp wird, trag'' ich den Brüller von meiner Alten ins Pfandl!', '[{"kategorie": "wörtlich", "text": "\"Wenn s''Geld knapp wird, versetze ich den Brillantring meiner Frau in der Pfandleihe!\"  2. Wenn Ebbe in der Kasse ist, landet der Klunker von meiner Frau im Pfandhaus!  3. Wenn’s wieder finster wird am Konto, geht der Brillantring meiner Alten auf Zeitreise ins [[Dorotheum]]!"}]'::jsonb, 'ins Pfandl troong'),
  ('ins-pfandl-haun', 'ins Pfandl haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'ins Pfandl hauen', '[{"kategorie": "wörtlich, Küchenjargon", "text": "\"in die Pfanne schmeißen\" (Fleischstück, etc.), \"in der Pfanne braten\", \"in der Pfanne anbraten\""}, {"kategorie": "fig.", "text": "\"etwas zur Verpfändung in die Pfandleihanstalt bringen\", \"etwas zur Pfandleihe bringen\", \"etwas im Pfandhaus versetzen\""}]'::jsonb, 'Hau ma s''Fleisch ins Pfandl - I bin aum Vahungan!'),
  ('hau-ma-s-fleisch-ins-pfandl-i-bin-aum-vahungan', 'Hau ma s''Fleisch ins Pfandl - I bin aum Vahungan!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Hau mir das Fleisch in die Pfanne - ich bin am Verhungern!', '[{"kategorie": "wörtlich", "text": "\"Leg das Fleisch in die Pfanne, ich sterbe vor Hunger!\"  2. Schmeiß das Steak endlich in die Pfanne – ich hab Bärenhunger!  3. Jetzt aber flott – das Fleisch muss in die Pfanne, sonst fall ich vom Stuhl!"}]'::jsonb, 'ins Pfandl haun'),
  ('waunns-goeoed-knopp-wiad-hau-i-in-bruella-von-meina-oidn-ins-pfandl', 'Waunns Gööd knopp wiad, hau I in Brülla von meina Oidn ins Pfandl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn das Geld knapp wird, hau ich den Brüller von meiner Alten ins Pfandl!', '[{"kategorie": "wörtlich", "text": "\"Wenn s''Geld knapp wird, versetze ich den Brillantring meiner Frau in der Pfandleihe!\"  2. Wenn Ebbe in der Kasse ist, landet der Klunker von meiner Frau im Pfandhaus!  3. Wenn’s wieder finster wird am Konto, geht der Brillantring meiner Alten auf Zeitreise ins [[Dorotheum]]!"}]'::jsonb, 'ins Pfandl haun'),
  ('pfiat-di', 'Pfiat di!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Pfüat di!', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Behüt'' dich Gott!\"  (religiös geprägte Abschiedsformel aus einer Zeit, in der religiöse Floskeln in der Alltagssprache noch stark verbreitet waren - ähnlich wie [[Grüß Gott]], \"Ade\", etc.)"}, {"kategorie": "allg., Abschiedsgruß unter Freunden und Verwandten", "text": "\"Leb wohl!\"  3. \"Mach''s gut!\"  4. \"Man sieht sich!\"  5. \"Bis bald!\"  6. \"Ciao!\"  7. \"Tschüssi!\""}]'::jsonb, 'Pfiat di, mei klaane Zuckamaus - bis boid!'),
  ('pfiat-di-mei-klaane-zuckamaus-bis-boid', 'Pfiat di, mei klaane Zuckamaus - bis boid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pfiat di, meine kleine Zuckermaus - bis bald!', '[{"kategorie": "wörtlich", "text": "\"Leb wohl, meine kleine Zuckermaus – bis bald!\"  2. Ciao, mein kleines Zuckerstück – wir sehen uns bald wieder!  3. Tschüssi, mein süßes Honigtöpfchen, und auf ganz bald!"}]'::jsonb, ''),
  ('pfiat-di-und-babaa', 'Pfiat di und babaa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pfüat di und babaa!', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Behüt'' dich Gott und bye-bye!\""}, {"kategorie": "allg., Abschiedsgruß unter Freunden und Verwandten", "text": "\"Leb wohl, mach''s gut!\"  3. Tschüssi, man sieht sich!\"  4. \"Ciao, bis bald!\""}]'::jsonb, ''),
  ('bussi-babaa', 'Bussi, babaa!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Bussi, babaa!', '[{"kategorie": "wörtlich", "text": "\"Küsschen und bye-bye!\" (\"Bussi\"=\"Küsschen\" und \"babaa\"=eingedeutsche Dialektform vom englischen \"Bye-bye\" = [verkürzt für]: \"Good-bye\"=\"God be with ye\"=\"Gott sei mit dir!\")"}, {"kategorie": "allg.", "text": "\"Bussi, bis bald!\"  3. \"Küsschen, wir sehen uns!  4. Bye-bye, mach''s gut!"}]'::jsonb, ''),
  ('babaatschi-mamaatschi', 'Babaatschi, Mamaatschi!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Babaatschi, Mamaatschi!', '[{"kategorie": "wörtlich, Spaßreim", "text": "\"Tschüssilein, Mütterlein!\"  2. [[Pfiat di, Mamaatschi!]]  3. \"Bussi, Mutsi – und a Pfiat di mit Zuckerguss!\"  4. \"Tschüsschen, Muttchen!\""}]'::jsonb, ''),
  ('pfiat-di-good', 'Pfiat di Good!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Pfüat dich Gott!', '[{"kategorie": "wörtlich", "text": "\"Behüte dich Gott!\"  (religiös geprägte Abschiedsformel aus einer Zeit, in der religiöse Floskeln in der Alltagssprache noch stark verbreitet waren - ähnlich wie [[Grüß Gott]], \"Ade\", etc.)"}, {"kategorie": "allg., Abschiedsgruß unter Freunden und Verwandten", "text": "\"Leb wohl!\"  3. \"Mach''s gut!\"  4. \"Man sieht sich!\"  5. \"Bis bald!\"  6. \"Ciao!\"  7. \"Tschüssi!\""}]'::jsonb, 'Pfiat di Good, du oide Krood!'),
  ('pfiat-di-good-du-oide-krood', 'Pfiat di Good, du oide Krood!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Pfüat dich Gott, du alte Krot''!', '[{"kategorie": "wörtlich, Spaßreim als Abschiedsgruß unter Freunden und Verwandten", "text": "\"Behüt dich Gott, du alte Krot''!\"  2. \"Leb wohl, du alte Kröte!\"  3. \"Ade, du alte Krötengestalt!\"  4. [[Ciao, Kakao!]]"}]'::jsonb, 'Pfiat di Good!'),
  ('tschau-kaukau', 'Tschau, Kaukau!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ciao, Kakao!', '[{"kategorie": "wörtlich, Spaßreim als Abschiedsgruß unter Freunden und Verwandten", "text": "\"Ciao Kakao!\"  2. \"Tschüssikowkski!\"  3. \"Tschüss mit ü!\"  4. [[Babaatschi!]]  5. [[Babaa und foi ned!]]  6. \"Pfiat di Good, du oide Krood!\""}]'::jsonb, ''),
  ('seawas-wos-hobds-jetzt-wiida-augschdoeoed', 'Seawas, wos hobds jetzt wiida augschdööd?!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Servus, was habt ihr jetzt wieder angestellt!?', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, was habt ihr jetzt wieder angestellt?\"  2. Himmel noch mal, was habt ihr denn jetzt schon wieder verbockt?  3. Jössasnaa, muss ich schon wieder die Feuerwehr rufen, oder reicht ein Eimer Wasser?"}]'::jsonb, ''),
  ('salve-oida-roeoema-wos-mochd-s-imperium', 'Salve, oida Rööma - wos mochd''s Imperium?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Salve, alter Römer - was macht das Imperium?', '[{"kategorie": "wörtlich", "text": "\"Servus, alter Römer - was macht das Imperium?\"  2. Sei gegrüßt, alter Römer – wie läuft''s im Exil?  3. Hallo, alter Knabe – was gibt''s Neues?"}]'::jsonb, ''),
  ('seeas-waunnsd-do-gas-gibsd-hauds-da-in-oasch-ins-handschuachfachl', 'Seeas, waunnsd do Gas gibsd, hauds da in Oasch ins Handschuachfachl!', '', '', '', 'Wiener Mechaniker-Slang', 'Servus, wenn du da Gas gibst, haut''s dir den Arsch ins Handschuhfach!', '[{"kategorie": "wörtlich", "text": "\"Heilige Scheiße, wenn du da da Gas gibst, fliegt dir der Arsch durch die Rückenlehne!\"  2. Mannomann, wenn du da aufs Gas trittst, klebt dir der Rücken an der Sitzlehne wie Sekundenkleber!  3. Alter Schwede, das Teil geht ab wie ein Raketenarsch mit Vollgas!"}]'::jsonb, ''),
  ('seeas-oida-ollas-rodscha', 'Seeas Oida, ollas rodscha?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Servus Alter, alles roger?', '[{"kategorie": "wörtlich, Jugendjargon", "text": "\"Servus, Alter, alles okay?\"  2. \"Hallo, Kumpel, geht''s gut?\"  2. \"Hey, [[Digga]], alles fit?\"  4. Hi, Alter, wie läuft''s?\""}]'::jsonb, ''),
  ('seawas-oide-hittn', 'Seawas, oide Hittn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Servus, alte Hütten!', '[{"kategorie": "wörtlich", "text": "\"Servus, alter Junge!\"  2. \"Lange nicht gesehen, alter Freund!\"  3. \"Hey, du Urgestein!\"  4. \"Na wie geht''s, Alter?\""}]'::jsonb, ''),
  ('seeas-oide-hittn', 'Seeas, oide Hittn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Servus, alte Hütten!', '[{"kategorie": "wörtlich", "text": "\"Servus, alter Junge!\"  2. \"Lange nicht gesehen, alter Freund!\"  3. \"Hey, du Urgestein!\"  4. \"Na wie geht''s, Alter?\""}]'::jsonb, ''),
  ('in-seawas-mochn', 'in Seawas mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'den Servus machen', '[{"kategorie": "wörtlich", "text": "\"den Diener machen\" (vom lateinischen \"servus\"=\"Diener\", als Grußformel ursprünglich in der Bedeutung \"Ihr Diener!\" - wie beispielsweise in der Höflichkeitsfloskel \"Servus humillimus!\"=\"Ihr untertänigster Diener!“)"}, {"kategorie": "mil.", "text": "salutieren, den militärischen Gruß ausführen, aufsalutieren"}, {"kategorie": "allg.", "text": "\"eine Verbeugung machen\", jemanden respektvoll grüßen, sich vor jemandem verneigen, jemandem seine Ehrerbietung erweisen"}, {"kategorie": "allg", "text": "\"sich verabschieden\", \"einen Abgang machen\", \"seinen Abschied nehmen\", \"Lebewohl sagen\""}, {"kategorie": "auch", "text": "\"sterben\", \"von der Bühne des Lebens abtreten\", [[die Patschen strecken]], [[ein]] Bankerl reißen"}]'::jsonb, 'Waunn da Offizia aufd Kommandobruckn kummd, miassma olle in Seawas mochn!'),
  ('waunn-da-offizia-aufd-kommandobruckn-kummd-miassma-olle-in-seawas-mochn', 'Waunn da Offizia aufd Kommandobruckn kummd, miassma olle in Seawas mochn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn der Offizier auf die Kommandobrücke kommt, müssen wir alle den Servus machen!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Offizier die Kommandobrücke betritt, müssen wir alle aufsalutieren!\"  2. Sobald der Offizier auf der Kommandobrücke erscheint, heißt es für uns: aufsalutieren!  3. Sobald der ranghöchste Offizier die Brücke betritt, ist unsererseits Salut zu erweisen!"}]'::jsonb, 'in Seawas mochn'),
  ('buaschn-i-muass-an-seawas-reissn-sunst-hob-i-dahaam-wiida-an-koeoech-mit-meina-oidn', 'Buaschn, I muass an Seawas reissn - sunst hob I dahaam wiida an Kööch mit meina Oidn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Burschen, ich muss den Servus machen - sonst hab ich daheim wieder einen Kööch mit meiner Alten!', '[{"kategorie": "wörtlich", "text": "\"Burschen, ich  muss mich jetzt von euch verabschieden - sonst hab ich daheim wieder einen Streit mit meiner Alten!\"  2. Leute, ich muss jetzt einen Abgang machen – sonst gibt’s daheim wieder Krach mit meiner Frau!  3. Freunde, ich muss von euch jetzt Abschied nehmen, sonst schmeißt mich meine bessere Hälfte heut noch aus der Wohnung!"}]'::jsonb, ''),
  ('leidln-i-moch-in-seawas-woa-schee-mit-eich', 'Leidln, I moch in Seawas - woa schee mit eich!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Leute, ich mache den Servus - war schön mit euch!', '[{"kategorie": "wörtlich", "text": "\"Leute, ich verabschiede mich - war schön mit euch!\"  2. Leute, ich mach mich dann mal auf den Weg – hat mich gefreut!  3. Leute, ich sag Adieu – es war mir eine echte Freude!"}]'::jsonb, 'in Seawas mochn'),
  ('waunn-da-schaeaef-glaubd-dass-i-imma-in-seawas-moch-waunna-bei-de-tia-einekummd-oda-aussgeed-hoda-si-teischd', 'Waunn da Schääf glaubd, dass I imma in Seawas moch, waunna bei de Tia einekummd oda aussgeed, hoda si teischd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Chef glaubt, dass ich immer den Servus mache, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Chef meint, ich würde ihn jedes Mal höflich begrüßen und verabschieden, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!\"  2. Wenn der Boss denkt, ich spring jedes Mal auf und sag brav Servus, wenn er kommt oder geht – hat er sich geschnitten!  3. Wenn der Chef erwartet, dass ich bei jedem Türklappen einen Diener mache – hat er sich im Jahrhundert geirrt!"}]'::jsonb, ''),
  ('iagendwaunn-miass-ma-olle-in-seawas-mochn-owa-bis-duathii-woima-leebm-liibn-und-lochn', 'Iagendwaunn miass ma olle in Seawas mochn - owa bis duathii woima leebm, liibn und lochn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Irgendwann müssen wir alle den Servus machen - aber bis dahin wollen wir leben, lieben und lachen!', '[{"kategorie": "wörtlich", "text": "\"Irgendwann müssen wir alle von der Bühne des Lebens abtreten - aber bis dahin lasst uns feiern, lieben und lachen!\"  2. Eines Tages heißt es für uns alle Lebewohl – aber bis dahin wollen wir leben, lieben und lachen!  3. Irgendwann heißt’s: Tschüssikowski – aber bis dahin lassen wir’s richtig krachen!"}]'::jsonb, 'in Seawas mochn'),
  ('an-seawas-reissn', 'an Seawas reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Servus reißen', '[{"kategorie": "wörtlich", "text": "\"einen Diener machen\" (vom lateinischen \"servus\"=\"Diener\", als Grußformel ursprünglich in der Bedeutung \"Ihr Diener!\" - wie beispielsweise in der Höflichkeitsfloskel \"Servus humillimus!\"=\"Ihr untertänigster Diener!“)"}, {"kategorie": "mil.", "text": "salutieren, den militärischen Gruß ausführen, aufsalutieren"}, {"kategorie": "allg.", "text": "\"eine Verbeugung machen\", jemanden respektvoll grüßen, sich vor jemandem verneigen, jemandem seine Ehrerbietung erweisen"}, {"kategorie": "allg", "text": "\"sich verabschieden\", \"einen Abgang machen\", \"seinen Abschied nehmen\", \"Lebewohl sagen\""}, {"kategorie": "auch", "text": "\"sterben\", \"von der Bühne des Lebens abtreten\", [[die Patschen strecken]], [[ein]] Bankerl reißen"}]'::jsonb, 'Waunn da Offizia aufd Kommandobruckn kummd, miassma olle an Seawas reissn!'),
  ('waunn-da-offizia-aufd-kommandobruckn-kummd-miassma-olle-an-seawas-reissn', 'Waunn da Offizia aufd Kommandobruckn kummd, miassma olle an Seawas reissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn der Offizier auf die Kommandobrücke kommt, müssen wir alle einen Servus reißen!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Offizier die Kommandobrücke betritt, müssen wir alle aufsalutieren!\"  2. Sobald der Offizier auf der Kommandobrücke erscheint, heißt es für uns: aufsalutieren!  3. Sobald der ranghöchste Offizier die Brücke betritt, ist unsererseits Salut zu erweisen!"}]'::jsonb, 'an Seawas reissn'),
  ('waunn-da-schaeaef-glaubd-dass-i-imma-an-seawas-reiss-waunna-bei-de-tia-einekummd-oda-aussgeed-hoda-si-teischd', 'Waunn da Schääf glaubd, dass I imma an Seawas reiss, waunna bei de Tia einekummd oda aussgeed, hoda si teischd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn der Chef glaubt, dass ich immer einen Servus reiße, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Chef meint, ich würde ihn jedes Mal höflich begrüßen und verabschieden, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!\"  2. Wenn der Boss denkt, ich spring jedes Mal auf und sag brav Servus, wenn er kommt oder geht – hat er sich geschnitten!  3. Wenn der Chef erwartet, dass ich bei jedem Türklappen einen Diener mache – hat er sich im Jahrhundert geirrt!"}]'::jsonb, ''),
  ('buaschn-i-reiss-an-seawas-woa-schee-mit-eich', 'Buaschn, I reiss an Seawas - woa schee mit eich!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Burschen, ich reiße einen Servus - war schön mit euch!', '[{"kategorie": "wörtlich", "text": "\"Jungs, ich verabschiede mich - war schön mit euch!\"  2. Leute, ich mach mich dann mal auf den Weg – hat mich gefreut!  3. Burschen, ich sag Adieu – es war mir echt ''ne Freude!"}]'::jsonb, ''),
  ('bevua-i-mein-seawas-reiss-mechd-i-schbian-dass-i-gleebd-hob', 'Bevua I mein Seawas reiss, mechd I schbian, dass I gleebd hob!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Bevor ich meinen Servus reiße, möchte ich spüren, dass ich gelebt habe!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich abtrete, will ich wissen, dass ich wirklich gelebt habe!\"  2. Bevor ich gehe, will ich das Leben nicht nur überlebt, sondern erlebt haben!  3. Bevor ich mich von der Bühne des Lebens verabschiede, will ich’s noch mal richtig krachen lassen!"}]'::jsonb, 'sein Seawas reissn'),
  ('iagendwaunn-miass-ma-olle-an-seawas-reissn-owa-bis-duathii-woima-leebm-liibn-und-lochn', 'Iagendwaunn miass ma olle an Seawas reissn - owa bis duathii woima leebm, liibn und lochn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Irgendwann müssen wir alle einen Servus reißen - aber bis dahin wollen wir leben, lieben und lachen!', '[{"kategorie": "wörtlich", "text": "\"Irgendwann müssen wir alle von der Bühne des Lebens abtreten - aber bis dahin lasst uns feiern, lieben und lachen!\"  2. Eines Tages heißt es für uns alle Lebewohl – aber bis dahin wollen wir leben, lieben und lachen!  3. Irgendwann heißt’s: Tschüssikowski – aber bis dahin lassen wir’s richtig krachen!"}]'::jsonb, ''),
  ('sein-seawas-reissn', 'sein Seawas reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'seinen Servus reißen', '[{"kategorie": "wörtlich", "text": "\"seinen Diener machen\" (vom lateinischen \"servus\"=\"Diener\", als Grußformel ursprünglich in der Bedeutung \"Ihr Diener!\" - wie beispielsweise in der Höflichkeitsfloskel \"Servus humillimus!\"=\"Ihr untertänigster Diener!“)"}, {"kategorie": "mil.", "text": "salutieren, den militärischen Gruß ausführen, aufsalutieren"}, {"kategorie": "allg.", "text": "\"eine Verbeugung machen\", jemanden respektvoll grüßen, sich vor jemandem verneigen, jemandem seine Ehrerbietung erweisen"}, {"kategorie": "allg", "text": "\"sich verabschieden\", \"einen Abgang machen\", \"seinen Abschied nehmen\", \"Lebewohl sagen\""}, {"kategorie": "auch", "text": "\"sterben\", \"von der Bühne des Lebens abtreten\", [[die Patschen strecken]], [[ein]] Bankerl reißen"}]'::jsonb, 'Bevua I mein Seawas reiss, mechd I schbian, dass I gleebd hob!'),
  ('waunn-da-offizia-aufd-kommandobruckn-kummd-miassma-olle-unsan-seawas-reissn', 'Waunn da Offizia aufd Kommandobruckn kummd, miassma olle unsan Seawas reissn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Offizier auf die Kommandobrücke kommt, müssen wir alle unseren Servus reißen!', '[{"kategorie": "wörtlich", "text": "\"Sobald der Offizier die Kommandobrücke betritt, müssen wir alle aufsalutieren!\"  2. Sobald der Offizier auf der Kommandobrücke erscheint, heißt es für uns: aufsalutieren!  3. Sobald der ranghöchste Offizier die Brücke betritt, ist unsererseits Salut zu erweisen!"}]'::jsonb, 'sein Seawas reissn'),
  ('waunn-da-schaeaef-glaubd-dass-i-imma-mein-seawas-reiss-waunna-bei-de-tia-einekummd-oda-aussgeed-hoda-si-teischd', 'Waunn da Schääf glaubd, dass I imma mein Seawas reiss, waunna bei de Tia einekummd oda aussgeed, hoda si teischd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Chef glaubt, dass ich immer meinen Servus reiße, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Chef meint, ich würde ihn jedes Mal höflich begrüßen und verabschieden, wenn er bei der Tür reinkommt oder rausgeht, hat er sich getäuscht!\"  2. Wenn der Boss denkt, ich spring jedes Mal auf und sag brav Servus, wenn er kommt oder geht – hat er sich geschnitten!  3. Wenn der Chef erwartet, dass ich bei jedem Türklappen einen Diener mache – hat er sich im Jahrhundert geirrt!"}]'::jsonb, ''),
  ('buaschn-i-reiss-mein-seawas-woa-schee-mit-eich', 'Buaschn, I reiss mein Seawas - woa schee mit eich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Burschen, ich reiße meinen Servus - war schön mit euch!', '[{"kategorie": "wörtlich", "text": "\"Jungs, ich verabschiede mich - war schön mit euch!\"  2. Leute, ich mach mich dann mal auf den Weg – hat mich gefreut!  3. Burschen, ich sag Adieu – es war mir echt ''ne Freude!"}]'::jsonb, 'sein Seawas reissn'),
  ('nau-seawas', 'Nau seawas!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na servus!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Servus Mahlzeit!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Oh Mann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. [[Na]] bumm!  12. [[Marantana]]!  13. [[Nau]] hawedeere!  14. [[Jössasnaa!]]"}]'::jsonb, 'Nau seawas, waunn des so weidageed, samma im Oasch!'),
  ('nau-seawas-waunn-des-so-weidageed-samma-im-oasch', 'Nau seawas, waunn des so weidageed, samma im Oasch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na servus, wenn das so weitergeht, sind wir im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Na bumm, wenn das so weitergeht, sind wir geliefert!\"  2. Heilige Scheiße, wenn das so weiterläuft, seh ich schwarz!  3. Servus Mahlzeit – das geht ganz sicher schief!"}]'::jsonb, 'Nau seawas!'),
  ('na-bumm', 'Na bumm!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na bumm!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Na servus!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Oh Mann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. [[Servus]] Mahlzeit!    12. [[Marantana]]!  12. [[Nau]] hawedeere!  13. [[Jössasnaa]]!"}]'::jsonb, 'Na bumm, mit so vüü Tiarln häd I ned grechnd!'),
  ('na-bumm-mit-so-vueue-tiarln-haed-i-ned-grechnd', 'Na bumm, mit so vüü Tiarln häd I ned grechnd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Na bumm, mit so viel Türln hätt ich nicht gerechnet!', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, mit so viel Toren hätte ich nicht gerechnet!\"  2. Heilige Scheiße - so viele Tore hätt ich wirklich nicht erwartet!  3. Alter Schwede, so viel Einschläge gab’s zuletzt im Weltkrieg!"}]'::jsonb, 'Na bumm!'),
  ('seawas-moizeid', 'Seawas Moizeid!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Servus Mahlzeit!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Na servus!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Mannomann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. [[Na]] bumm!  12. [[Marantana]]!  13. [[Nau]] hawedeere!  14. [[Jössasnaa!]]"}]'::jsonb, 'Seawas Moizeid, jetzd haumma in Solood!'),
  ('seawas-moizeid-jetzd-haumma-in-solood', 'Seawas Moizeid, jetzd haumma in Solood!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Servus Mahlzeit, jetzt haben wir den Salat!', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, jetzt haben wir den Salat!\"  2. \"Na bumm, jetzt haben wir ein echtes Problem am Hals!\"  3. \"Alter Schwede, jetzt haben wir den Schlamassel!\""}]'::jsonb, 'Seawas Moizeid!'),
  ('nau-hawedeere', 'Nau hawedeere!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na habe die Ehre!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Na servus!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Mannomann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. [[Na]] bumm!  12. [[Marantana]]!  13. [[Seawas]] Moizeid!  14. [[Jössasnaa!]]"}]'::jsonb, 'Nau hawedeere, wia san soowos von aum Oasch!'),
  ('nau-hawedeere-wia-san-soowos-von-aum-oasch', 'Nau hawedeere, wia san soowos von aum Oasch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Na habe die Ehre, wir sind sowas von am Arsch!', '[{"kategorie": "wörtlich", "text": "\"Heilige Scheiße, wir sind sowas von am Arsch!\"  2. Servus Mahlzeit, wir sind sowas von geliefert!  3. Mannomann, das war''s für uns!"}]'::jsonb, 'Nau hawedeere!'),
  ('na-seawas-gschaefd', 'Na seawas, Gschäfd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na servus, Geschäft!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Servus Mahlzeit!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Mannomann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. \"Mein lieber Schwan!\"  12. [[Na]] bumm!  13. [[Marantana]]!  14. [[Nau]] hawedeere!  15. [[Jössasnaa!]]"}]'::jsonb, 'Na seawas Gschäft! - Host dera iare Tuttln gseeng?'),
  ('na-seawas-gschaeft-host-dera-iare-tuttln-gseeng', 'Na seawas Gschäft! - Host dera iare Tuttln gseeng?', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Na servus Geschäft! Hast du die Tutteln von der gesehen?', '[{"kategorie": "wörtlich", "text": "\"Mannomann! Hast du die Titten von der gesehen?\"  2. \"Heiliger Bimbam, Alter! Hast du die Hupen von der gesehen?!\"  3. \"Alter Schwede, hast du gesehen, wieviel Holz die vor der Hüttn hat?!\""}]'::jsonb, 'Na seawas, Gschäfd!'),
  ('seawas-kaisa', 'Seawas Kaisa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Servus, Kaiser!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Servus Březina!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Mannomann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. \"Mein lieber Schwan!\"  12. [[Na]] bumm!  13. [[Marantana]]!  14. [[Nau]] hawedeere!  15. [[Jössasnaa!]]"}]'::jsonb, 'Seawas Kaisa, den hod da Schääf owa uandlich zsaummputzd!'),
  ('seawas-kaisa-den-hod-da-schaeaef-owa-uandlich-zsaummputzd', 'Seawas Kaisa, den hod da Schääf owa uandlich zsaummputzd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Servus Kaiser, den hat der Chef aber ordentlich zusammengeputzt!', '[{"kategorie": "wörtlich", "text": "\"Mein lieber Schwan, den hat der Chef aber ordentlich zusammengeputzt!\"  2. Alter Schwede, der hat vom Chef einen Einlauf bekommen, der sich gewaschen hat!  3. Mannomann, der wurde vom Chef zusammengefaltet wie ein Stück Papier!"}]'::jsonb, ''),
  ('seawas-bschesina', 'Seawas Bschesina!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Servus Březina!', '[{"kategorie": "Ausdruck des Erstaunens oder Entsetzens bzw. der Überraschung oder Bestürzung", "text": "[[Servus Kaiser!]]  2. \"Du meine Güte!\"  3. \"Du liebe Zeit!\"  4. \"Ach, herrje!\"  5. \"Mannomann!\"  6. \"Heiliger Bimbam!\"  7. \"Himmel noch mal!\"  8. \"Heilige Scheiße!\"  9. \"Heilige Maria, Mutter Gottes!\"  10. \"Alter Schwede!\"  11. \"Mein lieber Schwan!\"  12. [[Na]] bumm!  13. [[Marantana]]!  14. [[Nau]] hawedeere!  15. [[Jössasnaa!]]"}]'::jsonb, 'Seawas Bschesina, uma Hoa häds eam aufd Goschn ghaud!'),
  ('seawas-bschesina-uma-hoa-haeds-eam-aufd-goschn-ghaud', 'Seawas Bschesina, uma Hoa häds eam aufd Goschn ghaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Servus Březina, um ein Haar hätte es ihn auf die Goschn g''haut!', '[{"kategorie": "wörtlich", "text": "\"Heilige Scheiße, um ein Haar hätte es ihn auf die Fresse gehauen!\"  2. \"Na servus Mahlzeit, um ein Haar hätte er eine [[Brezen]] gerissen!\"  3. Heilige Maria, Mutter Gottes! Um ein Haar wäre er aufs Maul geflogen!"}]'::jsonb, 'Seawas Bschesina!'),
  ('waunn-mi-aana-auhallood-hob-i-eam-schoo-gfressn-i-bin-a-konsequenta-seawas-sooga', 'Waunn mi aana auhallood, hob I eam schoo gfressn - I bin a konsequenta ''Seawas''-Sooga!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn mich einer anhallot, habe ich schon gefressen - ich bin ein konsequenter Servus-Sager!', '[{"kategorie": "wörtlich", "text": "\"Wenn mir jemand mit ''Hallo'' kommt, ist bei mir der Ofen aus – ich bin ein konsequenter Servus-Sager!\"  2. Ich reagiere allergisch auf ''Hallo'' – bei mir gibt’s nur ''Servus''!  3. Sagt jemand ''Hallo'', bin ich innerlich schon ausgestiegen – ''Servus'' oder gar nix!"}]'::jsonb, ''),
  ('dideere-oide-hittn', 'Dideere, oide Hittn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dir d''Ehre, alte Hütten!', '[{"kategorie": "wörtlich", "text": "\"Habe die Ehre, alte Hütten!\"  2. (allg., Grußformel unter Du-Freunden): \"Servus, alter Freund!\"  3. [[Griass di, mei Haawara!]]"}]'::jsonb, 'Griass di, mei Haawara!'),
  ('dideere-is-des-a-iwaroschung', 'Dideere, is des a Iwaroschung!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Dir d''Ehre, ist das ''ne Überraschung!', '[{"kategorie": "wörtlich", "text": "\"Himmel noch mal, ist das ''ne Überraschung!\"  2. Ach du meine Güte, was für ''ne Überraschung!  3. Mannomann, Ich glaub, mich tritt ein Pferd – das ist ja der Hammer!"}]'::jsonb, ''),
  ('griass-di-mei-haawara', 'Griass di, mei Haawara!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Grüß dich, mein Haberer!', '[{"kategorie": "wörtlich", "text": "\"Grüß dich, mein Freund!\"  2. (allg., Grußformel unter Du-Freunden): \"Servus, alter Freund!\"  3. [[Dideere, oide Hittn!]]"}]'::jsonb, 'Dideere, oide Hittn!'),
  ('deere-oida', 'Deere, Oida!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'D''Ehre, Alter!', '[{"kategorie": "wörtlich", "text": "\"Habe die Ehre, Alter!\"  2. (allg., Grußformel unter Du-Freunden): \"Servus, alter Freund!\"  3. [[Griass di, mei Haawara!]]"}]'::jsonb, ''),
  ('deere-wia-teia-des-ollas-wuan-is', 'Deere, wia teia des ollas wuan is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'D''Ehre, wie teuer das alles geworden ist!', '[{"kategorie": "wörtlich", "text": "\"Du meine Güte, wie teuer das alles geworden ist!\"  2. \"Alter Schwede, ist das alles teuer geworden!\"  3. Marantana, es ist kaum zu glauben, welche Summen inzwischen verlangt werden!"}]'::jsonb, ''),
  ('djeere-es-beidln', 'Djeere, es Beidln!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'D''Ehre, ihr Beidln!', '[{"kategorie": "wörtlich", "text": "\"Habe die Ehre, ihr Säcke!\"  2. \"Servus, ihr Säcke!\"  3. [[Griass eich, es Beidln!]]"}]'::jsonb, 'Griass eich, es Beidln!'),
  ('djeere-des-kaunn-jo-noo-lustig-wean', 'Djeere, des kaunn jo noo lustig wean!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'D''Ehre, das kann ja noch lustig werden!', '[{"kategorie": "wörtlich", "text": "\"Du liebe Zeit, das kann ja noch lustig werden!\"  2. Na servus – das fängt ja schon gut an!  3. Alter Schwede, da kommt noch einiges auf uns zu!"}]'::jsonb, ''),
  ('griass-eich-es-beidln', 'Griass eich, es Beidln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Grüß euch, ihr Beidln!', '[{"kategorie": "wörtlich", "text": "\"Ich begrüße euch, ihr Säcke!\"  2. \"Servus, ihr Säcke!\"  3. [[Djeere, es Beidln!]]"}]'::jsonb, 'Djeere, es Beidln!'),
  ('na-hawedeere-sowos-howi-no-ned-gseeng', 'Na hawedeere, sowos howi no ned gseeng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na habe die Ehre, so etwas habe ich noch nicht gesehen!', '[{"kategorie": "wörtlich", "text": "Na servus, sowas ist mir noch nie untergekommen!  2. Das gibt''s ja nicht, sowas habe ich noch nie erlebt!  3. Heiliger Bimbam, das darf doch nicht wahr sein!"}]'::jsonb, ''),
  ('hawediina-jetzt-samma-im-oasch-dahaam', 'Hawediina, jetzt samma im Oasch dahaam!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Habe Diener, jetzt sind wir im Arsch daheim!', '[{"kategorie": "wörtlich", "text": "\"Mein lieber Schwan, jetzt sind wir im Arsch!\"  2. Heiliger Bimbam, jetzt sind wir endgültig geliefert!  3. Du meine Güte, die Katastrophe perfekt – nichts geht mehr!"}]'::jsonb, ''),
  ('tschuess-mit-ue', 'Tschüss mit ü!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Tschüss mit ü!', '[{"kategorie": "wörtlich", "text": "\"Tschüss mit ü!\" (Nonsensbildung von \"tschüss\" - Abschiedsgruß, abgeleitet vom spanischen \"A dios!\"=\"Zu Gott!\" - Im 17. Jahrhundert übernahmen Seeleute und Händler im norddeutschen Raum das französische \"A dios\", woraus im Niederdeutschen dann \"adjüs\" und schließlich durch lautliche Abschleifung und Vereinfachung die vertrautere Form \"tschüss\" wurde)"}, {"kategorie": "Jugendsprache", "text": "\"Tschüssikowski!\"  3. [[Tschaui!]]  4. [[Babaatschi!]]  5. [[Babaa und foi ned!]]  6. \"Pfiat di Good, du oide Krood!\""}]'::jsonb, ''),
  ('na-pfiat-di-good', 'Na pfiat di Good!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na pfüat dich Gott!', '[{"kategorie": "Ausruf des Erstaunens oder Entsetzens", "text": "\"Du liebe Zeit!\"  2. \"Na gute Nacht!\"  3. \"Heiliger Bimbam!\"  4. \"Du meine Güte!\"  5. \"Heilige Scheiße!\""}, {"kategorie": "", "text": "[[Marantana!]]  7. [[Jössasnaa!]]"}]'::jsonb, 'Na pfiat di Good! Des host wiaklich gsoogd - vua ia?'),
  ('na-pfiat-di-good-des-host-wiaklich-gsoogd-vua-ia', 'Na pfiat di Good! Des host wiaklich gsoogd - vua ia?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na pfüat dich Gott! Des hast du wirklich gesagt – vor ihr?!', '[{"kategorie": "wörtlich", "text": "\"Na gute Nacht! Des hast du wirklich gesagt – vor ihr?!\"  2. Heilige Scheiße! Das hast du echt gesagt – vor ihrer Nase?!  3. Ach du meine Güte, das hast du echt gesagt – direkt vor ihr?!"}]'::jsonb, ''),
  ('na-guade-nochd', 'Na guade Nochd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Na gute Nacht!', '[{"kategorie": "Ausruf des Erstaunens oder Entsetzens", "text": "\"Du liebe Zeit!\"  2. \"Na servus!\"  3. \"Heiliger Bimbam!\"  4. \"Du meine Güte!\"  5. \"Heilige Scheiße!\""}, {"kategorie": "", "text": "[[Marantana!]]  7. [[Jössasnaa!]]  8. [[Heilige Maria, Mutter Gottes!]]"}]'::jsonb, 'Na guade Nochd, schau da den au - dea hod si a Peckal mittn ins Gsichd schdechn lossn!'),
  ('na-guade-nochd-schau-da-den-au-dea-hod-si-a-peckal-mittn-ins-gsichd-schdechn-lossn', 'Na guade Nochd, schau da den au - dea hod si a Peckal mittn ins Gsichd schdechn lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Na gute Nacht, schau dir den an - der hat sich ein Peckerl mitten ins Gesicht stechen lassen!', '[{"kategorie": "wörtlich", "text": "\"Heilige Scheiße, schau dir den an - der hat sich ein Tattoo mitten ins Gesicht stechen lassen!\"  2. Du liebe Zeit, sieh dir den an - der hat sich das Gesicht zutätowieren lassen!  3. Heilige Maria, Mutter Gottes, eine Tätowierung mitten im Gesicht?! Der spinnt doch!"}]'::jsonb, 'Na guade Nochd!'),
  ('pfiad-di-good-ochtal', 'Pfiad-di-Good-Ochtal', 'das', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Pfüat-dich-Gott-Achterl', '[{"kategorie": "wörtlich", "text": "\"das Lebewohl-Achterl\" (Determinativkompositum aus \"Pfiad-di- Good\"=\"Lebewohl\" und [[Achterl]]=\"ein Achtelliter Wein)"}, {"kategorie": "allg.", "text": "\"Abschiiedsachterl\" (\"letztes Achtelglas Wein vor dem Abschiednehmen\"), [[Reiseachterl]] (Glas mit einem Achtelliter Wein, das als letztes vor dem Weggehen noch getrunken wird), [[Fluchtachterl]]"}]'::jsonb, ''),
  ('kumm-oida-a-letzts-pfiad-di-good-achtal-hau-ma-uns-no-eine', 'Kumm Oida, a letzts Pfiad-di-Good-Achtal hau ma uns no eine!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Komm, Alter, ein letztes Pfüat-dich-Gott-Achterl hauen wir uns noch rein!', '[{"kategorie": "wörtlich", "text": "\"Los, Junge, ein letztes Achterl Wein zum Abschied nehmen wir uns noch zur Brust!\"  2. Komm schon, mein Freund, ein letztes Fluchtachterl geht noch, oder?  3. Kumpel, bevor wir uns verabschieden: Noch ein letzter Schluck fürs Herz!"}]'::jsonb, ''),
  ('pfiad-di-good-lackal', 'Pfiad-di-Good-Lackal', 'das', '', '', 'Echte Wiener Schmähperlen', 'Pfüat-dich-Gott-Lackerl', '[{"kategorie": "wörtlich", "text": "\"das Lebewohl-Pfützchen\" (Determinativkompositum aus \"Pfiad-di- Good\"=\"Lebewohl\" und \"Lackerl\" [Verkleinerungsform von \"Lacke\"]=\"Pfützchen\")"}, {"kategorie": "allg.", "text": "\"letzter Getränkerest im Glas\" (von dem man sich wehmütig mit einem \"Pfiat-di-Good!\" verabschiedet, ehe man ihn schließlich austrinkt), \"der letzte Tropfen\", \"der allerletzte Schluck\", \"der letzte Rest vom Schützenfest\""}, {"kategorie": "scherzhaft für", "text": "\"feuchter Gruß aus der Blase\"  (in Anspielung darauf, dass einem vor lauter Schreck ein Pfützchen in die Hose entfleucht), \"Angsttrröpfchen\", [[Mini-Liik]]"}]'::jsonb, 'Zum Pfiad-di-Good-Lackal soogd ma schweigend Prost!'),
  ('zum-pfiad-di-good-lackal-soogd-ma-schweigend-prost', 'Zum Pfiad-di-Good-Lackal soogd ma schweigend Prost!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Zum Pfüat-dich-Gott-Lackerl sagt man schweigend ''Prost''!', '[{"kategorie": "wörtlich", "text": "\"Vom allerletzten Schluck verabschiedet man sich schweigend mit einem ''Prost'' im Geiste!\"  2. Dem letzten Tropfen begegnet man in Stille – mit einem stillen ''Zum Wohl'' im Herzen!  3. Wenn das Glas leer wird, bleibt nur ein Prost im Geiste – ohne Worte, aber voller Wehmut!"}]'::jsonb, ''),
  ('wiara-de-puffn-zoong-hod-hob-i-schoo-a-pfiad-di-good-lackal-gmochd', 'Wiara de Puffn zoong hod, hob I schoo a Pfiad-di-Good-Lackal gmochd!', '', '', '', 'Wiener Gaunersprache', 'Wie er die Puffen gezogen hat, hab ich schon ein ''Pfüat-dich-Gott-Lackerl'' gemacht!', '[{"kategorie": "wörtlich", "text": "\"Als er die Waffe zog, ist mir ein Angsttröpfchen in die Hose entfleucht!\"  2. Als er die Knarre zog, hab ich mir vor Schreck ein Pfützchen in die Hose gepieselt!  3. Ich sag’s, wie’s ist: Beim Anblick der Pistole hab ich ein Mini-Leak gehabt und bin leicht ausgelaufen!"}]'::jsonb, ''),
  ('pfiad-di-good-lackal-du-woasd-kuaz-owa-koestlich', 'Pfiad di Good, Lackal - du woasd kuaz, owa köstlich!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Pfüat dich Gott, Lackerl – du warst kurz, aber köstlich!', '[{"kategorie": "wörtlich", "text": "\"Bye-bye, mein allerletztes Tropferl – du warst kurz, aber köstlich!\"  2. Mach’s gut, du letzter Schluck – du warst wenig, aber wunderbar!  3. Adieu, du allerletzter Tropfen – kaum da, schon ein Teil von mir!"}]'::jsonb, ''),
  ('pfiad-di-good-lackal-a-wunda-dass-i-mi-ned-augschissn-hob', 'Pfiad di Good, Lackal - a Wunda, dass I mi ned augschissn hob!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Pfüat-dich-Gott, Lackerl - ein Wunder, dass ich mich nicht angeschissen habe!', '[{"kategorie": "wörtlich", "text": "\"Mannomann, ein feuchter Gruß aus der Blase – ein Wunder, dass ich mich nicht gleich angeschissen habe!\"  2. Na servus, da kam erst ein Tropfen – und dann fast die ganze Familie hinterher!  3. Na bumm, willkommen im Hosenbund, Pfützchen der Angst - ein Wunder, dass ich mir nicht auch gleich ins Hemd geschissen habe!"}]'::jsonb, 'Pfiad di Good, Lackal!'),
  ('mini-liik', 'Mini-Liik', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Mini-Leak', '[{"kategorie": "wörtlich", "text": "\"Mini-Leak\" (vom englischen \"mini\"=\"klein\" und \"leak\"=\"undichte Stelle\")"}, {"kategorie": "Jugendjargon, scherzhaft für", "text": "\"feuchter Gruß aus der Blase\"  (in Anspielung darauf, dass einem vor lauter Schreck ein Pfützchen in die Hose entfleucht), \"Angsttrröpfchen\", [[Pfiat-di-Good-Lackal]]"}]'::jsonb, 'Bro, I hob fost an Mini-Liik ghobd!'),
  ('bro-i-hob-fost-an-mini-liik-ghobd', 'Bro, I hob fost an Mini-Liik ghobd!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Bro, ich hab fast ''nen Mini-Leak gehabt!', '[{"kategorie": "wörtlich", "text": "\"Bruder, ich hatte fast ein Mini-Leck!\"  2. Alter, ich hätt um ein Haar in die Hose gemacht!  3. Junge, mir wär jetzt fast ein Lackerl in die Hose gegangen!"}]'::jsonb, ''),
  ('richt-ollas-hea-fian-ualaub-owa-bitte-ned-wiida-in-gaunzn-hausschdaund', 'Richt ollas hea fian Ualaub, owa bitte ned wiida in gaunzn Hausschdaund!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Richte alles her für den Urlaub - aber bitte nicht wieder den ganzen Hausstand!', '[{"kategorie": "wörtlich", "text": "\"Richte alles her für den Urlaub – aber diesmal ohne den ganzen Hausrat, wir fahren nicht in den Krieg!\"  2. Mach alles klar für den Urlaub – aber nicht wieder die halbe Wohnung miteinpacken!  3. Bereite alles für den Urlaub vor, aber bitte nur das Nötigste – wir verreisen, wir siedeln nicht um!"}]'::jsonb, ''),
  ('dea-hod-mein-flitza-wiida-echt-geil-heagrichd-schaud-aus-wia-neich', 'Dea hod mein Flitza wiida echt geil heagrichd - schaud aus wia neich!', '', '', '', 'Wiener Mechaniker-Slang', 'Der hat meinen Flitzer wieder echt geil hergerichtet - schaut aus wie neu!', '[{"kategorie": "wörtlich", "text": "\"Der hat meine Karre wieder voll auf Vordermann gebracht – sieht aus wie frisch vom Band!\"  2. Krass, wie der die Kiste wieder hingebogen hat – schaut aus wie frisch gekauft!  3. Der Mechaniker hat merinen Wagen komplett instand gesetzt – der blitzt jetzt wie’n Showcar!"}]'::jsonb, ''),
  ('si-richd-si-nua-noo-schnoeoe-hea-daunn-gemma-los', 'Si richd si nua noo schnöö hea, daunn gemma los!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie richtet sich nur noch schnell her, dann gehen wir los!', '[{"kategorie": "wörtlich", "text": "\"Sie macht sich nur noch schnell fertig, dann gehen wir los!\"  2. \"Wir machen uns gleich auf den Weg - sie muss sich nur noch kurz aufhübschen!\"  3. \"Sie macht sich noch kurz zurecht, dann können wir los!\""}]'::jsonb, ''),
  ('i-richt-schnoeoe-noo-wos-zum-essn-hea-bevua-de-gaest-kumma', 'I richt schnöö noo wos zum Essn hea, bevua de Gäst kumma!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich richte schnell noch was zum Essen her, bevor die Gäste kommen!', '[{"kategorie": "wörtlich", "text": "\"Ich bereite schnell noch eine Kleinigkeit zu, bevor die Gäste da sind!\"  2. Ich richte schnell noch ein paar Teller an, bevor die Gäste kommen!  3. Ich zauber noch schnell was auf den Tisch, bevor die Gäste da sind!"}]'::jsonb, ''),
  ('pflanzn-kaunnsd-wem-aundan-owa-ned-mi', 'Pflanzn kaunnsd wem aundan, owa ned mi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Pflanzen kannst du jemand anderen, aber nicht mich!', '[{"kategorie": "wörtlich", "text": "\"Verarschen kannst du jemand anderen, aber nicht mich!\"  2. Mich kannst du nicht verschaukeln - da musst du früher aufstehen!  3. Ich lass mich von dir nicht vorführen - such dir jemand anderen!"}]'::jsonb, ''),
  ('i-loss-mi-von-eam-do-ned-pflanzn', 'I loss mi von eam do ned pflanzn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich lasse mich von ihm doch nicht pflanzen', '[{"kategorie": "wörtlich", "text": "\"Ich lasse mich von ihm doch nicht zum Narren halten!\"  2. Frotzeln kann der wen anderen, aber nicht mich!  3. Ich lasse mich von ihm doch nicht verschaukeln!"}]'::jsonb, ''),
  ('i-loss-mi-von-eam-do-ned-frotzln', 'I loss mi von eam do ned frotzln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich lasse mich von ihm doch nicht frotzeln', '[{"kategorie": "wörtlich", "text": "\"Ich lasse mich von ihm doch nicht zum Narren halten!\"  2. Verarschen kann der wen anderen, aber nicht mich!  3. Ich lasse mich von ihm doch nicht verschaukeln!"}]'::jsonb, ''),
  ('i-loss-mi-von-eam-do-ned-haekaln', 'I loss mi von eam do ned häkaln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich lasse mich von ihm doch nicht häkerln', '[{"kategorie": "wörtlich", "text": "\"Ich lasse mich von ihm doch nicht zum Narren halten!\"  2. Pflanzen kann der wen anderen, aber nicht mich!  3. Ich lasse mich von ihm doch nicht verschaukeln!"}]'::jsonb, ''),
  ('i-loss-mi-von-eam-do-ned-papialn', 'I loss mi von eam do ned papialn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich lasse mich von ihm doch nicht papierlen', '[{"kategorie": "wörtlich", "text": "\"Ich lasse mich von ihm doch nicht zum Narren halten!\"  2. Verarschen kann der wen anderen, aber nicht mich!  3. Ich lasse mich von ihm doch nicht verschaukeln!"}]'::jsonb, ''),
